        type == Token.NEG ||
        type == Token.BITNOT) {
        Preconditions.checkState(n.hasOneChild());

        if (NodeUtil.isExpressionNode(parent)) {
          // If the value of the NOT isn't used, then just throw
          // away the operator
          parent.replaceChild(n, n.removeFirstChild());
          t.getCompiler().reportCodeChange();
          return;
