    if (type == Token.ADD) {
      tryFoldAdd(t, n, left, right, parent);
      return;
    }
    if (type == Token.SUB ||
        type == Token.MUL ||
        type == Token.DIV) {
      tryFoldArithmetic(t, n, left, right, parent);
      return;
    }

    if (type == Token.LT ||
        type == Token.GT ||
        type == Token.LE ||
        type == Token.GE ||
        type == Token.EQ ||
        type == Token.NE ||
        type == Token.SHEQ ||
        type == Token.SHNE) {
      tryFoldComparison(t, n, left, right, parent);
      return;
